export function hsvToRgb(t,e,n){const r=n*e,o=r*(1-Math.abs(t/60%2-1)),a=n-r;let s=0,u=0,i=0;return t<60?(s=r,u=o):t<120?(s=o,u=r):t<180?(u=r,i=o):t<240?(u=o,i=r):t<300?(s=o,i=r):(s=r,i=o),[Math.round(255*(s+a)),Math.round(255*(u+a)),Math.round(255*(i+a))]}export function rgbToHex(t,e,n){return"#"+[t,e,n].map(t=>t.toString(16).padStart(2,"0")).join("")}export function hexToHsv(t){const e=parseInt(t.slice(1,3),16)/255,n=parseInt(t.slice(3,5),16)/255,r=parseInt(t.slice(5,7),16)/255,o=Math.max(e,n,r),a=o-Math.min(e,n,r);let s=0;return a&&(s=o===e?60*((n-r)/a+(n<r?6:0)):o===n?60*((r-e)/a+2):60*((e-n)/a+4)),{h:Math.round(s)%360,s:o?a/o:0,v:o}}export function normalizeHex(t){return t=t.trim().toLowerCase().replace(/^#?/,"#"),/^#[0-9a-f]{3}$/.test(t)&&(t="#"+t[1]+t[1]+t[2]+t[2]+t[3]+t[3]),/^#[0-9a-f]{6}$/.test(t)||/^#[0-9a-f]{8}$/.test(t)?t:null}